<script>document.addEventListener('DOMContentLoaded',function(){var tabs=document.querySelectorAll('.marketing-tab'),panels=document.querySelectorAll('.marketing-panel');tabs.forEach(function(tab){tab.addEventListener('click',function(){tabs.forEach(function(t){t.classList.remove('active')});panels.forEach(function(p){p.classList.remove('active')});tab.classList.add('active');var panel=document.querySelector('[data-panel="'+tab.dataset.tab+'"]');if(panel)panel.classList.add('active')})});var durationCards=document.querySelectorAll('.duration-option');durationCards.forEach(function(card){card.addEventListener('click',function(){durationCards.forEach(function(c){c.classList.remove('active')});card.classList.add('active');var input=card.querySelector('input');if(input)input.checked=true})});});</script>
